# Liebermann, Gesetze I p. 659: Lond 32 C 6a–32 E (32 E 1 runs on to p. 660: see p660.py)
D = lambda de, en: (de, en)
LOND_ED = 'This passage is not part of ECf or ECf retr: it is one of the additions of the London collection (Leges Anglorum s. XIII in. Londoniis collectae), which Liebermann prints across the page as an insertion into ECf retr. 32 (32 A–E, pp. 655–660). The dictionary cites it as “ECf 32 …”, so it is kept with ECf here.'
GALF = 'The London compiler copies 32 D–D 6 from Geoffrey of Monmouth I 2 (Liebermann’s margin: “Galf. Monm. I 2”), printed in smaller type; Liebermann gives the passage because Lambard and later editors left it unprinted (his note d).'
LD = D('<i>fehlt Ld</i>', 'lacking in Ld')
CO = D('<i>fehlt Co</i>', 'lacking in Co')
B = D('Bryt. <i>Ld</i>', 'Bryt. Ld')
FD = D('<i>diese werthlose Abschrift aus der</i> 32 D 7 <i>citirten</i> Hist. Britonum <i>liess Lambard und daher jeder spätere Editor ungedruckt</i>', 'Lambard, and so every later editor, left unprinted this worthless copy from the Hist. Britonum cited at 32 D 7')
def L(n, text, notes, margin=None, extra=None):
    c = {'code': 'ECf', 'n': n, 'page': 659, 'keys': ['ECf ' + n], 'text': text, 'notes': notes, 'editorial': [LOND_ED] + (extra or [])}
    if margin: c['margin'] = margin
    return c
